function FocusField() {
  const inputRef = useRef(null)
  return <><input ref={inputRef} /><button onClick={() => inputRef.current?.focus()}>Фокус</button></>
}

function SearchField({ ref }) {
  const inputRef = useRef(null)
  useImperativeHandle(ref, () => ({ focus: () => inputRef.current?.focus() }), [])
  return <input ref={inputRef} />
}

import { createPortal } from "react-dom"

function Overlay({ children }) {
  return createPortal(children, document.body)
}

import { useCallback } from "react"
function Row({ id, nodes }) {
  const bind = useCallback(node => {
    nodes.set(id, node)
    return () => { nodes.delete(id) }
  }, [id, nodes])
  return <li ref={bind}>{id}</li>
}
// nodes - стабильный реестр, принадлежащий вызывающему коду.

import { useEffect, useRef } from "react"
function WidgetHost({ createWidget }) {
  const host = useRef(null)
  useEffect(() => {
    const widget = createWidget(host.current)
    return () => widget.destroy()
  }, [createWidget])
  return <div ref={host} />
}
// createWidget стабилен по контракту; внутренностями host управляет виджет.
